import {localInput, instantFromInput, dayKey, onDay, monthCells} from './schedule.js';
import {marked} from '../../../assets/vendors/projects/marked.js';
import DOMPurify from '../../../assets/vendors/projects/purify.js';

import {API_BASE_URL} from '../../shared/data/config.js';
const API=API_BASE_URL;
const S={projects:[],selected:null,tab:'overview',focus:'0',search:'',filter:'all',month:new Date(),timer:null,ready:false,todayAgenda:null,pendingTasks:new Set()};
const labels={task:'Tarea',note:'Nota',document:'Documento',event:'Evento',reminder:'Recordatorio',purchase:'Compra',inventory:'Material'};
const statuses={todo:'Pendiente',doing:'En curso',done:'Completada',pending:'Pendiente',cancelled:'Cancelado',scheduled:'Programado',planned:'Prevista',ordered:'Pedida',received:'Recibida'};
const priority={low:'Baja',medium:'Media',high:'Alta',urgent:'Urgente'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const timeZone=Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';
const date=v=>v?new Intl.DateTimeFormat('es-ES',{day:'2-digit',month:'short',timeZone}).format(new Date(v)):'Sin fecha';
const button=(text,action,extra='',cls='')=>`<button class="pr-button ${cls}" type="button" data-action="${action}" ${extra}>${text}</button>`;
const current=()=>S.projects.find(p=>p.id===S.selected);
const projects=()=>current()?[current()]:S.projects.filter(p=>!p.template&&p.status!=='archived');
const entries=()=>projects().flatMap(p=>p.entries.map(e=>({...e,projectId:p.id,projectTitle:p.title})));
const empty=text=>`<div class="pr-empty">${text}</div>`;
async function api(path,method='GET',data){const r=await fetch(API+path,{method,credentials:'include',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,cache:'no-store'});let b;try{b=await r.json();}catch{throw new Error('No se pudo contactar con Bookshell');}if(!r.ok)throw new Error(b.error||'No se pudo guardar');return b;}
function notice(message){let e=document.querySelector('#projects-message');if(!e)return;e.textContent=message;e.className='pr-error';e.hidden=false;}
async function refresh(){if(S.pendingTasks.size)return;try{const b=await api('/projects');S.projects=b.projects;S.ready=true;if(S.tab==='today')S.todayAgenda=(await api('/projects/notifications/agenda')).agenda;if(S.selected&&!current())S.selected=null;render();}catch(e){if(S.ready)notice(e.message);}}
function progress(p){return `<div class="pr-progress" role="progressbar" aria-label="Tareas completadas" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${p.stats.taskProgress}"><span style="width:${p.stats.taskProgress}%"></span></div><div class="pr-card-meta"><span>${p.stats.done} / ${p.stats.total} tareas</span><span>${p.stats.taskProgress}%</span></div>`;}
function taskRow(t){return `<div class="pr-task ${t.status==='done'?'done':''}"><input type="checkbox" aria-label="Completar ${esc(t.title)}" data-toggle="${t.id}" data-project="${t.projectId}" ${t.status==='done'?'checked':''} ${S.pendingTasks.has(t.id)?'disabled':''}><div class="pr-task-content"><button class="pr-link" data-edit="${t.id}" data-project="${t.projectId}">${esc(t.title)}</button><small>${t.dueAt?date(t.dueAt):'Sin fecha'} · ${t.priority==='urgent'?'Urgente':priority[t.priority]} ${t.scheduleType==='estimated'&&t.dueAt?'· Estimada':''}${t.blockedBy?.length?' · '+t.blockedBy.length+' bloqueo(s)':''}${t.parentId?' · Subtarea':''}${t.reminders?.some(r=>r.enabled&&r.status==='pending')?' · 🔔 '+t.reminders.filter(r=>r.enabled&&r.status==='pending').length+' aviso(s)':''}</small></div></div>`;}
function stats(){const es=entries(),ts=es.filter(e=>e.kind==='task'),done=ts.filter(t=>t.status==='done').length;const blocked=ts.filter(t=>t.status!=='done'&&t.blockedBy.length).length;const values=[[projects().length,'Proyectos activos','◈'],[ts.filter(t=>t.status!=='done').length,'Tareas pendientes','☑'],[blocked,'Bloqueos detectados','↳'],[ts.length?Math.round(done/ts.length*100)+'%':'0%','Tareas completadas','↗']];return `<div class="pr-stats">${values.map(([v,k,i])=>`<div class="pr-stat"><span class="pr-stat-mark">${i}</span><span>${k}</span><strong>${v}</strong><span>${k==='Tareas completadas'?`${done} de ${ts.length} tareas`:'Datos sincronizados'}</span></div>`).join('')}</div>`;}
function chart(){const ts=entries().filter(e=>e.kind==='task');const counts=['done','doing','todo'].map(s=>ts.filter(t=>t.status===s).length);const colors=['#a4e8b0','#6d9fbd','#304837'];let offset=0;return `<div class="pr-chart-wrap"><svg class="pr-donut" viewBox="0 0 120 120" role="img" aria-label="Distribución: ${counts[0]} completadas, ${counts[1]} en curso, ${counts[2]} pendientes"><circle cx="60" cy="60" r="46" fill="none" stroke="#263a2d" stroke-width="13"/>${counts.map((n,i)=>{const len=ts.length?n/ts.length*289:0;const s=`<circle cx="60" cy="60" r="46" fill="none" stroke="${colors[i]}" stroke-width="13" stroke-dasharray="${len} ${289-len}" stroke-dashoffset="${-offset}" transform="rotate(-90 60 60)"/>`;offset+=len;return s;}).join('')}<text x="60" y="60" text-anchor="middle" fill="#e1f0e5" font-size="25">${ts.length}</text><text x="60" y="77" text-anchor="middle" fill="#91a799" font-size="9">TAREAS</text></svg><div class="pr-legend">${counts.map((n,i)=>`<div><i style="background:${colors[i]}"></i>${['Completadas','En curso','Pendientes'][i]} <b>${n}</b></div>`).join('')}</div></div>`;}
function upcoming(){return entries().filter(e=>['event','reminder','task'].includes(e.kind)&&!['done','cancelled'].includes(e.status)&&(e.dueAt||e.startAt)).sort((a,b)=>(a.dueAt||a.startAt).localeCompare(b.dueAt||b.startAt)).slice(0,5);}
function agendaPanel(){const es=upcoming();return `<div class="pr-panel-head"><h2>Próximas fechas</h2><span class="pr-muted">${esc(timeZone)}</span></div>${es.map(e=>{const d=new Date(e.dueAt||e.startAt);return `<div class="pr-event"><div class="pr-datebox">${d.toLocaleDateString('es-ES',{day:'2-digit',timeZone})}<small>${d.toLocaleDateString('es-ES',{month:'short',timeZone})}</small></div><div><button class="pr-link" data-edit="${e.id}" data-project="${e.projectId}">${esc(e.title)}</button><p><small>${labels[e.kind]} · ${e.startAt?new Date(e.startAt).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit',timeZone}):''} · ${esc(e.projectTitle)}</small></p></div></div>`;}).join('')||empty('No hay fechas programadas')}<div style="margin-top:15px">${button('+ Recordatorio','new-entry','data-kind="reminder"')}</div>`;}
function dashboard(){const es=entries(),ts=es.filter(e=>e.kind==='task'&&!e.archived),now=new Date(),today=dayKey(now),weekEnd=new Date(now);weekEnd.setDate(weekEnd.getDate()+7);const open=ts.filter(t=>t.status!=='done'),due=t=>t.dueAt&&dayKey(new Date(t.dueAt));const todayTasks=open.filter(t=>due(t)===today),weekTasks=open.filter(t=>due(t)&&due(t)>=today&&due(t)<=dayKey(weekEnd)),blocked=open.filter(t=>t.blockedBy?.length),lateReminders=es.filter(e=>e.kind==='reminder'&&e.status==='pending'&&e.dueAt&&new Date(e.dueAt)<now),soon=es.filter(e=>['event','reminder'].includes(e.kind)&&e.status!=='cancelled'&&e.status!=='done'&&(e.dueAt||e.startAt)&&new Date(e.dueAt||e.startAt)>=now).sort((a,b)=>(a.dueAt||a.startAt).localeCompare(b.dueAt||b.startAt)).slice(0,3);const subset=(title,items,allTab='list')=>`<section class="pr-panel pr-focus" data-focus-panel="${({Hoy:0,'Esta semana':1,Bloqueadas:2})[title]}"><div class="pr-panel-head"><h2>${title}</h2><button class="pr-link" data-action="tab" data-tab="${allTab}">Ver todas</button><span class="pr-count">${items.length}</span></div>${items.slice(0,4).map(taskRow).join('')||empty(title==='Hoy'?'No hay tareas para hoy':title==='Bloqueadas'?'Sin bloqueos':'Sin tareas próximas')}</section>`;const ps=current()?[current()]:S.projects.filter(p=>!p.template&&p.status!=='archived');const note=es.filter(e=>['note','document'].includes(e.kind)).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,3);return `<section class="pr-overview-top"><div class="pr-overview-metric"><strong>${open.length}</strong><span>pendientes</span></div><div class="pr-overview-metric"><strong>${todayTasks.length}</strong><span>para hoy</span></div><div class="pr-overview-metric"><strong>${blocked.length}</strong><span>bloqueadas</span></div><div class="pr-overview-metric"><strong>${lateReminders.length}</strong><span>avisos vencidos</span></div></section><div class="pr-focus-switch" role="group" aria-label="Agenda del resumen">${['Hoy','Semana','Bloqueos','Agenda'].map((title,i)=>`<button type="button" data-action="focus" data-focus="${i}" aria-pressed="${S.focus===String(i)}">${title}</button>`).join('')}</div><div class="pr-focus-grid" data-focus="${S.focus}">${subset('Hoy',todayTasks)}${subset('Esta semana',weekTasks)}${subset('Bloqueadas',blocked)}<section class="pr-panel pr-focus" data-focus-panel="3"><div class="pr-panel-head"><h2>Próximos eventos y recordatorios</h2><button class="pr-link" data-action="tab" data-tab="calendar">Calendario</button></div>${soon.map(e=>`<div class="pr-event"><div class="pr-datebox">${new Date(e.dueAt||e.startAt).toLocaleDateString('es-ES',{day:'2-digit',month:'short',timeZone})}</div><button class="pr-link" data-edit="${e.id}" data-project="${e.projectId}">${esc(e.title)}<small>${labels[e.kind]} · ${e.startAt?new Date(e.startAt).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit',timeZone}):''} · ${esc(e.projectTitle)}</small></button></div>`).join('')||empty('Sin eventos próximos')}${button('+ Recordatorio','new-entry','data-kind="reminder"')}</section></div><section class="pr-panel pr-projects-strip"><div class="pr-panel-head"><h2>${current()?'Este proyecto':'Proyectos'}</h2>${button('+','new-project','','primary')}</div><div class="pr-project-cards">${ps.map(p=>`<button class="pr-project-card" data-open="${p.id}"><span>${esc(p.title)}</span><b>${p.stats.taskProgress}%</b>${progress(p)}<small>Avance físico: ${p.physicalProgress===null?'sin confirmar':p.physicalProgress+'%'}</small></button>`).join('')||empty('Crea tu primer proyecto')}</div></section><div class="pr-lower-grid"><section class="pr-panel"><div class="pr-panel-head"><h2>Actividad reciente</h2><button class="pr-link" data-action="tab" data-tab="activity">Ver actividad</button></div><div id="projects-overview-activity">Cargando…</div></section><section class="pr-panel"><div class="pr-panel-head"><h2>Notas recientes</h2><button class="pr-link" data-action="tab" data-tab="note">Ver notas</button></div>${note.map(n=>`<div class="pr-note-row"><button class="pr-link" data-read="${n.id}" data-project="${n.projectId}">${esc(n.title)}<small>${esc(n.projectTitle)} · ${date(n.updatedAt)}</small></button></div>`).join('')||empty('Sin notas')}</section></div>`;}
function filtered(es){es=es.filter(e=>e.kind!=='task'||(S.filter==='archived'?e.archived:!e.archived));const q=S.search.toLowerCase();return es.filter(e=>(S.filter==='all'||S.filter==='archived'&&e.archived||e.priority===S.filter||e.status===S.filter||S.filter==='blocked'&&e.blockedBy?.length)&&(!q||[e.title,e.description,e.assignee,e.category,e.projectTitle].join(' ').toLowerCase().includes(q)));}
function toolbar(kindName='task'){return `<div class="pr-toolbar"><input class="pr-search" id="projects-search" placeholder="Buscar en esta vista…" aria-label="Buscar" value="${esc(S.search)}">${S.tab==='list'||S.tab==='kanban'?`<select class="pr-select" id="projects-filter" aria-label="Filtrar"><option value="all">Todas las tareas</option>${Object.entries({...priority,...statuses,blocked:'Bloqueadas',archived:'Archivadas'}).map(([k,v])=>`<option value="${k}" ${S.filter===k?'selected':''}>${v}</option>`).join('')}</select>`:''}${button('+ '+labels[kindName],'new-entry',`data-kind="${kindName}"`,'primary')}</div>`;}
function kanban(){const tasks=filtered(entries().filter(e=>e.kind==='task'));return toolbar()+`<div class="pr-kanban">${['todo','doing','done'].map(s=>`<section class="pr-kanban-column" data-drop="${s}"><div class="pr-panel-head"><h3>${statuses[s]}</h3><span class="pr-count">${tasks.filter(t=>t.status===s).length}</span></div>${tasks.filter(t=>t.status===s).map(t=>`<article class="pr-card" draggable="true" data-drag="${t.id}" data-project="${t.projectId}"><span class="pr-pill ${t.priority}">${priority[t.priority]}</span><div class="pr-card-title"><button class="pr-link" data-edit="${t.id}" data-project="${t.projectId}">${esc(t.title)}</button></div><p>${esc(t.projectTitle)}</p><div class="pr-card-meta"><span>${date(t.dueAt)}</span><span>${t.blockedBy.length?'⛓ '+t.blockedBy.length:'○ '+esc(t.assignee||'Sin asignar')}</span></div></article>`).join('')||empty('Sin tareas')}</section>`).join('')}</div>`;}
function list(){const ts=filtered(entries().filter(e=>e.kind==='task'));return toolbar()+`<div class="pr-panel"><div class="pr-tasks">${ts.map(taskRow).join('')||empty('No hay tareas con estos filtros')}</div></div>`;}
function calendarItems(){const es=entries().filter(e=>['task','event','reminder'].includes(e.kind)&&e.status!=='cancelled'&&!e.archived),items=es.filter(e=>e.kind!=='reminder'||!e.taskId),seen=new Set(items.filter(e=>e.kind==='task'&&(e.dueAt||e.startAt)).map(e=>e.id+':'+dayKey(e.dueAt||e.startAt)));for(const t of es.filter(e=>e.kind==='task'&&e.status!=='done'))for(const r of t.reminders||[]){if(!r.enabled||r.status!=='pending'||!r.at)continue;const key=t.id+':'+dayKey(r.at);if(!seen.has(key)){seen.add(key);items.push({...t,startAt:null,dueAt:r.at,noticeDate:true});}}return items;}
function calendar(){
 const m=S.month,es=filtered(calendarItems()),today=dayKey(new Date());
 return toolbar('event')+`<section class="pr-panel pr-calendar"><div class="pr-panel-head">${button('‹','month','data-delta="-1" aria-label="Mes anterior"')}<h2>${esc(m.toLocaleDateString('es-ES',{month:'long',year:'numeric'}))}</h2>${button('›','month','data-delta="1" aria-label="Mes siguiente"')}</div><div class="pr-calendar-tools">${button('Hoy','today')}<small>Tareas <i class="pr-dot task"></i> Eventos <i class="pr-dot event"></i> Avisos <i class="pr-dot reminder"></i></small></div><div class="pr-month">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=>`<div class="pr-weekday">${d}</div>`).join('')}${monthCells(m).map(d=>{const key=dayKey(d),items=es.filter(e=>onDay(e,key));return `<button type="button" data-day="${key}" class="pr-day ${d.getMonth()!==m.getMonth()?'off':''} ${key===today?'today':''}" ${key===today?'aria-current="date"':''} aria-label="${esc(d.toLocaleDateString('es-ES',{day:'numeric',month:'long'}))}: ${items.length} elementos"><span class="pr-day-number">${d.getDate()}</span>${items.slice(0,2).map((e,i)=>`<span class="pr-calendar-event ${e.kind} ${i===1?'pr-second-event':''}" title="${esc(e.title)}">${esc(e.title)}</span>`).join('')}${items.length>2?`<span class="pr-calendar-more pr-wide-count">+${items.length-2} más</span>`:''}${items.length>1?`<span class="pr-calendar-more pr-narrow-count">+${items.length-1} más</span>`:''}</button>`;}).join('')}</div><p class="pr-notice">Pulsa un día para ver y gestionar su agenda · ${esc(timeZone)}</p></section>`;
}
function dayAgenda(key){
 const items=calendarItems().filter(e=>onDay(e,key)).sort((a,b)=>(a.startAt||a.dueAt||'').localeCompare(b.startAt||b.dueAt||''));
 const d=dialog(new Date(key+'T12:00:00').toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'}),`<div class="pr-day-agenda"><p class="pr-muted">${items.length} elementos · ${esc(timeZone)}</p>${items.map(e=>`<article class="pr-agenda-row"><span class="pr-dot ${e.kind}" aria-hidden="true"></span><div><button class="pr-link" data-day-edit="${e.id}" data-project="${e.projectId}">${esc(e.title)}</button><small>${labels[e.kind]}${e.noticeDate?' · Aviso programado':''} · ${esc(e.projectTitle)} · ${statuses[e.status]||''}${e.scheduleType==='estimated'?' · Estimada':''}</small><small>${new Date(e.kind==='event'?e.startAt||e.dueAt:e.dueAt||e.startAt).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit',timeZone})}</small></div>${['task','event','reminder'].includes(e.kind)&&e.status!=='done'?button('Completar','day-complete',`data-id="${e.id}" data-project="${e.projectId}"`):'<span class="pr-muted">✓</span>'}</article>`).join('')||empty('Sin elementos programados para esta fecha')}</div>`);
 for(const b of d.querySelectorAll('[data-day-edit]'))b.onclick=()=>{const e=findEntry(b.dataset.dayEdit,b.dataset.project);entryForm(e.kind,e,b.dataset.project);};
 for(const b of d.querySelectorAll('[data-action=day-complete]'))b.onclick=async()=>{b.disabled=true;const e=findEntry(b.dataset.id,b.dataset.project);try{await api(`/projects/${b.dataset.project}/entries/${e.id}`,'PATCH',{kind:e.kind,version:e.version,data:{status:'done'}});await refresh();dayAgenda(key);}catch(err){formError(err);b.disabled=false;}};
}
function timeline(){const ts=filtered(entries().filter(e=>e.kind==='task'));const dated=ts.filter(t=>t.startAt||t.dueAt);const min=Math.min(Date.now(),...dated.map(t=>new Date(t.startAt||t.dueAt).getTime()));const max=Math.max(min+7*864e5,...dated.map(t=>new Date(t.dueAt||t.startAt).getTime()));return toolbar()+`<div class="pr-panel"><div class="pr-panel-head"><h2>Cronograma</h2><small>${date(new Date(min))} — ${date(new Date(max))}</small></div><div class="pr-table-wrap">${dated.map(t=>{const a=new Date(t.startAt||t.dueAt).getTime();const b=new Date(t.dueAt||t.startAt).getTime();return `<div class="pr-timeline-row"><button class="pr-link" data-edit="${t.id}" data-project="${t.projectId}">${esc(t.title)}<br><small class="pr-muted">${date(t.startAt)} → ${date(t.dueAt)}</small></button><div class="pr-track"><span class="pr-track-bar ${t.blockedBy.length?'blocked':''}" style="left:${(a-min)/(max-min)*95}%;width:${Math.max(2,(b-a)/(max-min)*95)}%"></span></div></div>`;}).join('')||empty('Asigna fechas de inicio y vencimiento a las tareas')}</div><p class="pr-notice">${ts.length-dated.length} tareas sin fecha · Las barras ámbar indican dependencias pendientes.</p></div>`;}
function documents(k){const es=filtered(entries().filter(e=>e.kind===k));return toolbar(k)+`<div class="pr-document-grid">${es.map(e=>`<article class="pr-panel"><div class="pr-icon-tile">${k==='document'?'⌘':'▤'}</div><h3 class="pr-card-title"><button class="pr-link" data-read="${e.id}" data-project="${e.projectId}">${esc(e.title)}</button></h3><p class="pr-muted">${esc(e.category)} · ${esc(e.projectTitle)}</p><p class="pr-muted">${esc(e.description.replace(/[#*\x60]/g,'').slice(0,100))}</p><div class="pr-card-meta"><span>${date(e.updatedAt)}</span>${button('Editar','edit-entry',`data-id="${e.id}" data-project="${e.projectId}"`)}</div></article>`).join('')||empty('No hay resultados. Crea un registro para empezar.')}</div>`;}
function materials(){const es=filtered(entries().filter(e=>['purchase','inventory'].includes(e.kind)));return toolbar('purchase')+`<div style="margin-bottom:12px">${button('+ Material en inventario','new-entry','data-kind="inventory"')}</div><div class="pr-panel pr-table-wrap"><table class="pr-table"><thead><tr><th>Material / compra</th><th>Proyecto</th><th>Cantidad</th><th>Estado / ubicación</th><th>Coste total</th></tr></thead><tbody>${es.map(e=>`<tr><td><button class="pr-link" data-edit="${e.id}" data-project="${e.projectId}">${esc(e.title)}</button></td><td>${esc(e.projectTitle)}</td><td>${e.quantity} ${esc(e.unit||'uds')}</td><td>${esc(statuses[e.status]||e.location||'—')}${e.kind==='inventory'&&e.quantity<e.minimum?' · ⚠ Bajo mínimo':''}</td><td>${e.kind==='purchase'?new Intl.NumberFormat('es-ES',{style:'currency',currency:e.currency}).format(e.quantity*e.unitCost):'—'}</td></tr>`).join('')}</tbody></table>${!es.length?empty('Registra compras, entregas y existencias'):''}</div>`;}
function todayView(){
 const a=S.todayAgenda;if(!a)return empty('Cargando tu agenda…');const scoped=rows=>current()?rows.filter(e=>e.projectId===S.selected):rows;
 const tasks=scoped(a.tasks).map(t=>({...t,...findEntry(t.id,t.projectId)})).filter(t=>t.status!=='done'&&!t.archived),reminders=scoped(a.reminders),events=scoped(a.events),late=tasks.filter(t=>t.overdue),today=tasks.filter(t=>!t.overdue);
 const panel=(title,items,renderItem)=>`<section class="pr-panel"><div class="pr-panel-head"><h2>${title}</h2><span class="pr-count">${items.length}</span></div>${items.map(renderItem).join('')||empty('Todo al día')}</section>`;
 const row=e=>`<div class="pr-task"><div class="pr-task-content">${e.legacy?`<a class="pr-link" href="${esc(e.url)}">${esc(e.title)}</a>`:`<button class="pr-link" data-edit="${e.id}" data-project="${e.projectId}">${esc(e.title)}</button>`}<small>${esc(e.projectTitle)} · ${date(e.dueAt||e.startAt)}</small></div></div>`;
 return `<div class="pr-toolbar"><div><h2 class="pr-section-title">Tu agenda de hoy</h2><p class="pr-notice">${esc(a.date)} · ${esc(a.timezone)} · Cada tarea se cuenta una sola vez</p></div>${button('Actualizar','refresh')}</div><div class="pr-today-grid">${panel('Tareas de hoy',today,taskRow)}${panel('Tareas vencidas',late,taskRow)}${panel('Recordatorios independientes',reminders,row)}${panel('Eventos',events,row)}</div>`;
}
function noticeState(r){return r.delivery==='sent'?'Aceptado por push':r.status==='cancelled'?'Cancelado':r.status==='done'?'Finalizado':({uncertain:'Envío incierto',expired:'Caducado · no enviado',no_subscription:'Sin dispositivo activo',retry:'Reintento pendiente',failed:'Fallo de envío'})[r.delivery]||(!r.enabled&&r.enabled!==undefined||r.notify===false?'Desactivado':'Programado');}
function reminderEditor(e){const rs=e?.reminders||[],options=[[0,'Al vencer'],[15,'15 min antes'],[60,'1 hora antes'],[1440,'1 día antes']];
 const custom=rs.filter(r=>r.enabled&&r.offsetMinutes===null);
 return `<fieldset class="pr-task-notifications pr-full"><legend>Avisos de esta tarea</legend><div class="pr-alert-presets">${options.map(([n,label])=>`<label class="pr-alert-choice"><input type="checkbox" name="alertOffset" value="${n}" ${rs.some(r=>r.enabled&&r.offsetMinutes===n)?'checked':''}><span>${label}</span></label>`).join('')}</div><div class="pr-custom-alerts">${custom.map(r=>customAlertRow(r)).join('')}</div><div class="pr-actions">${button('Personalizado','add-task-alert')}${button('Sin aviso','clear-task-alerts')}</div><p class="pr-notice">Se cancelan al completar o archivar la tarea. Los avisos relativos siguen su vencimiento.</p>${rs.length?`<details class="pr-alert-history"><summary>Estado de ${rs.length} aviso(s)</summary>${rs.map(r=>`<p class="pr-notice">${esc(r.at?new Date(r.at).toLocaleString('es-ES',{timeZone}):'Sin fecha')} · ${esc(noticeState(r))}</p>`).join('')}</details>`:''}</fieldset>`;
}
function customAlertRow(r={}){return `<div class="pr-custom-alert"><label>Fecha personalizada<input type="datetime-local" value="${esc(localInput(r.at))}" data-task-alert-at data-alert-id="${r.id||''}" required></label>${button('✕','remove-task-alert','aria-label="Quitar aviso"')}</div>`;}
function progressCircle(p){const total=p.stats.total;const done=p.stats.done;const pct=p.stats.taskProgress;const dash=2*Math.PI*34;return `<div class="pr-circle-wrap"><svg class="pr-circle" viewBox="0 0 84 84" role="img" aria-label="Progreso administrativo ${pct}%"><circle class="pr-circle-track" cx="42" cy="42" r="34"/><circle class="pr-circle-value" cx="42" cy="42" r="34" stroke-dasharray="${dash}" stroke-dashoffset="${dash*(1-pct/100)}"/><text x="42" y="47" text-anchor="middle">${pct}%</text></svg><div><strong>${done} de ${total} tareas</strong><small>Progreso administrativo</small><small>Avance físico: ${p.physicalProgress===null?'sin confirmar':p.physicalProgress+'%'}</small></div></div>`;}
function moreMenu(){const p=current();const d=dialog('Más opciones',`<div class="pr-quick-menu">${button('Actualizar','refresh')}${button('Accesos rápidos','quick-access')}${button('Conexión con ChatGPT','access')}${p?button('Editar proyecto','edit-project'):button('Plantillas y archivo','library')}</div>`);for(const b of d.querySelectorAll('[data-action]'))b.onclick=()=>{const a=b.dataset.action;d.close();if(a==='refresh')void refresh();if(a==='quick-access')document.querySelector('[data-global-fab-toggle]')?.click();if(a==='access')void access();if(a==='edit-project')projectForm(current());if(a==='library')library();};}
function render(){if(!S.ready)return;const p=current();const root=document.getElementById('projects-app');const navScroll=root.querySelector('.pr-tabs')?.scrollLeft||0;root.innerHTML=`<header class="pr-top"><div class="pr-heading">${p?`<button type="button" class="pr-breadcrumb-button" data-action="global">‹ Todos los proyectos</button>`:''}<div class="pr-kicker">BOOKSHELL / ${p?'PROYECTO':'PROJECTS'}</div><h1>${p?esc(p.title):'Proyectos'}<span style="color:#70c9a8">.</span></h1>${p?progressCircle(p):'<p>Lo importante, a la vista.</p>'}</div><div class="pr-actions"><span class="pr-sync" aria-label="Sincronizado">● ${new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}</span><button class="pr-button pr-more" type="button" aria-label="Más opciones" data-action="more">•••</button><button class="pr-button pr-create" type="button" aria-label="Nuevo proyecto" data-action="new-project"><span aria-hidden="true">＋</span><span class="pr-create-label">Nuevo</span></button></div></header><div id="projects-message" hidden></div><div class="pr-toolbar pr-project-switch"><label for="projects-select">Proyecto</label><select class="pr-select" id="projects-select" aria-label="Seleccionar proyecto"><option value="">Todos los proyectos</option>${S.projects.map(x=>`<option value="${x.id}" ${x.id===S.selected?'selected':''}>${x.template?'Plantilla · ':x.status==='archived'?'Archivado · ':''}${esc(x.title)}</option>`).join('')}</select>${p?button('Editar','edit-project'):button('Plantillas y archivo','library')}</div>${p?`<div class="pr-detail-head"><div class="pr-project-meta"><span class="pr-pill ${p.color}">${p.template?'Plantilla':p.status==='archived'?'Archivado':p.status==='paused'?'En pausa':'Activo'}</span>${p.dueAt?`<span class="pr-pill ${p.dueAtType==='estimated'?'estimated':''}">${p.dueAtType==='estimated'?'Objetivo estimado':'Objetivo'} · ${date(p.dueAt)}</span>`:''}<span class="pr-pill">${p.stats.blocked} bloqueos</span></div><p>${esc(p.description)}</p><small>Avance físico: ${p.physicalProgress===null?'sin confirmar':p.physicalProgress+'% · '+esc(p.physicalEvidence)}</small></div>`:''}<nav class="pr-tabs" aria-label="Vistas de Proyectos">${[['overview','Resumen'],['today','Hoy'],['kanban','Kanban'],['list','Lista'],['calendar','Calendario'],['timeline','Cronograma'],['note','Notas'],['document','Documentación'],['materials','Materiales'],['reminders','Recordatorios'],['activity','Actividad']].map(([k,l])=>`<button class="pr-tab ${S.tab===k?'active':''}" type="button" data-action="tab" data-tab="${k}" aria-current="${S.tab===k?'page':'false'}">${l}</button>`).join('')}</nav><div id="projects-content">${({overview:dashboard,today:todayView,kanban,list,calendar,timeline,note:()=>documents('note'),document:()=>documents('document'),materials,reminders:()=>toolbar('reminder')+`<div class="pr-panel">${filtered(entries().filter(e=>e.kind==='reminder')).map(e=>`<div class="pr-task"><div class="pr-task-content"><button class="pr-link" data-edit="${e.id}" data-project="${e.projectId}">${esc(e.title)}</button><small>${date(e.dueAt)} · ${statuses[e.status]} · ${e.taskId?'Vinculado a tarea · ':e.linkReview?'Revisar vínculo · ':''}${noticeState(e)}</small></div></div>`).join('')||empty('Sin recordatorios')}</div>`,activity:()=>'<div class="pr-panel" id="projects-history">Cargando historial…</div>'}[S.tab]||dashboard)()}</div>`;bind();root.querySelector('.pr-tabs').scrollLeft=navScroll;const nav=root.querySelector('.pr-tabs'),active=nav.querySelector('.pr-tab.active');if(active){const n=nav.getBoundingClientRect(),a=active.getBoundingClientRect();if(a.left<n.left)nav.scrollLeft-=n.left-a.left+12;else if(a.right>n.right)nav.scrollLeft+=a.right-n.right+12;}if(S.tab==='activity')void loadHistory();if(S.tab==='overview')void loadOverviewActivity();}

function dialog(title,content){
 const d=document.getElementById('projects-dialog');
 d.innerHTML=`<div class="pr-dialog-head"><div><span class="pr-kicker">BOOKSHELL / EDITOR</span><h2 id="projects-dialog-title">${esc(title)}</h2></div><button class="pr-button" type="button" data-close aria-label="Cerrar">✕</button></div><div class="pr-dialog-body">${content}</div>`;
 d.setAttribute('aria-labelledby','projects-dialog-title');
 const form=d.querySelector('form'),footer=form?.querySelector('footer');
 const error=document.createElement('div');error.id='projects-form-error';error.setAttribute('role','alert');
 if(form){form.id='projects-editor';if(footer){for(const b of footer.querySelectorAll('[type=submit]'))b.setAttribute('form',form.id);footer.before(error);d.append(footer);}}else d.querySelector('.pr-dialog-body').append(error);
 const viewport=()=>{const v=window.visualViewport;d.style.setProperty('--pr-viewport-height',`${v?.height||innerHeight}px`);d.style.setProperty('--pr-viewport-top',`${v?.offsetTop||0}px`);};
 if(!d.open){d._returnFocus=document.activeElement;document.documentElement.classList.add('pr-modal-open');d.showModal();window.visualViewport?.addEventListener('resize',viewport);window.visualViewport?.addEventListener('scroll',viewport);d.onclose=()=>{window.visualViewport?.removeEventListener('resize',viewport);window.visualViewport?.removeEventListener('scroll',viewport);document.documentElement.classList.remove('pr-modal-open');d._returnFocus?.focus({preventScroll:true});};}
 d.querySelector('[data-close]').onclick=()=>d.close();viewport();d.querySelector('[data-close]').focus({preventScroll:true});return d;
}
const input=(name,label,value='',type='text')=>`<label data-field="${name}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${name==='title'?'required maxlength="300"':''}></label>`;
const select=(name,label,options,value,multiple=false)=>`<label data-field="${name}">${label}<select name="${name}" ${multiple?'multiple':''}>${Object.entries(options).map(([k,v])=>`<option value="${esc(k)}" ${(multiple?(value||[]).includes(k):k===value)?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
function formError(e){const el=document.getElementById('projects-form-error');if(el){el.textContent=e.message;el.className='pr-error';el.scrollIntoView({block:'nearest'});}}
function projectForm(p){const templates=S.projects.filter(p=>p.template);const d=dialog(p?'Editar proyecto':'Nuevo proyecto',`<form class="pr-project-form"><div class="pr-entry-main">${input('title','Nombre del proyecto',p?.title||'')}${select('status','Estado',{active:'Activo',paused:'En pausa',archived:'Archivado'},p?.status||'active')}${select('color','Color',{green:'Verde',blue:'Azul',amber:'Ámbar',violet:'Violeta'},p?.color||'green')}${input('dueAt','Fecha objetivo',localInput(p?.dueAt),'datetime-local')}${select('dueAtType','Tipo de objetivo',{estimated:'Estimado',confirmed:'Confirmado'},p?.dueAtType||'estimated')}<label class="pr-full">Descripción<textarea name="description">${esc(p?.description||'')}</textarea></label><p class="pr-notice pr-full">Fechas en ${esc(timeZone)}</p><details class="pr-advanced pr-full"><summary>Avance físico y plantillas</summary><div class="pr-form-grid">${input('physicalProgress','Avance físico (%) · vacío = sin confirmar',p?.physicalProgress??'','number')}${input('physicalEvidence','Evidencia del avance físico',p?.physicalEvidence||'')}</div><label><span><input name="template" type="checkbox" ${p?.template?'checked':''}> Guardar como plantilla reutilizable</span></label>${!p&&templates.length?select('templateId','Crear desde plantilla',{'':'Sin plantilla',...Object.fromEntries(templates.map(t=>[t.id,t.title]))},''):''}</details></div><footer class="pr-form-actions">${button('Cancelar','close')}<button class="pr-button primary" type="submit">Guardar proyecto</button></footer></form>`);d.querySelector('[data-action=close]').onclick=()=>d.close();d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;const b=Object.fromEntries(new FormData(f));try{f.querySelector('[type=submit]')?.setAttribute('disabled','');document.querySelector(`[form="${f.id}"][type=submit]`)?.setAttribute('disabled','');const data={title:b.title,description:b.description,color:b.color,status:b.status,dueAt:b.dueAt?instantFromInput(b.dueAt,p?.dueAt):null,dueAtType:b.dueAtType||'estimated',physicalProgress:b.physicalProgress===''?null:Number(b.physicalProgress),physicalEvidence:b.physicalEvidence,template:f.elements.template.checked};if(p){const confirmed=data.status!=='archived'||confirm('¿Archivar este proyecto? Sus datos se conservarán.');if(!confirmed)return;await api('/projects/'+p.id,'PATCH',{patch:data,version:p.version,confirmed});}else{const r=await api('/projects','POST',{project:data,templateId:b.templateId||undefined});S.selected=r.project.id;}d.close();await refresh();}catch(err){formError(err);}finally{d.querySelector('[type=submit]')?.removeAttribute('disabled');}};}
function findEntry(id,projectId){return S.projects.find(p=>p.id===projectId)?.entries.find(e=>e.id===id);}
function entryForm(k,e,projectId){
 const options=Object.fromEntries(S.projects.filter(p=>(!p.template&&p.status!=='archived')||p.id===projectId).map(p=>[p.id,p.title]));if(!Object.keys(options).length){projectForm();return;}
 projectId=projectId||S.selected||Object.keys(options)[0];const p=S.projects.find(p=>p.id===projectId);const tasks=p.entries.filter(t=>t.kind==='task'&&t.id!==e?.id);const rich=['note','document'].includes(k);let main='',advanced='';
 if(k==='task'){
  main=`${select('status','Estado',{todo:'Pendiente',doing:'En curso',done:'Completada'},e?.status||'todo')}${select('priority','Prioridad',priority,e?.priority||'medium')}<div class="pr-form-grid">${input('startAt','Fecha de inicio',localInput(e?.startAt),'datetime-local')}${input('dueAt','Vencimiento',localInput(e?.dueAt),'datetime-local')}</div>${select('scheduleType','Tipo de fecha',{estimated:'Estimación',confirmed:'Confirmada'},e?.scheduleType||'estimated')}<label class="pr-full">Descripción<textarea name="description">${esc(e?.description||'')}</textarea></label>`;
  advanced=`<details class="pr-advanced"><summary>Responsable, dependencias y detalles</summary><label><span><input type="checkbox" name="archived" ${e?.archived?'checked':''}> Archivar tarea y suspender sus avisos</span></label><div class="pr-form-grid">${input('assignee','Responsable',e?.assignee||'')}${input('estimatedMinutes','Duración estimada (minutos)',e?.estimatedMinutes??'','number')}${select('parentId','Tarea principal',{'':'Sin tarea principal',...Object.fromEntries(tasks.map(t=>[t.id,t.title]))},e?.parentId||'')}<label>Buscar dependencias<input type="search" class="pr-dependency-search" placeholder="Filtrar tareas"></label></div><div class="pr-dependency-list">${tasks.map(t=>`<label><input type="checkbox" name="dependsOn" value="${t.id}" ${(e?.dependsOn||[]).includes(t.id)?'checked':''}> <span>${esc(t.title)}</span></label>`).join('')||'<small>Sin otras tareas en este proyecto</small>'}</div><label><span><input type="checkbox" name="milestone" ${e?.milestone?'checked':''}> Hito del proyecto</span></label><label>Adjuntos · un título y enlace por línea<textarea name="attachmentsText" placeholder="Manual | https://…">${esc((e?.attachments||[]).map(a=>a.title+' | '+a.url).join('\n'))}</textarea></label><small>${e?.completedAt?'Completada el '+new Date(e.completedAt).toLocaleString('es-ES',{timeZone}):'La fecha real se registra al completar la tarea.'}</small></details>`;
 }else if(rich){main=`${input('category','Categoría',e?.category||(k==='note'?'General':'Técnica'))}<label class="pr-full">Contenido · Markdown<textarea name="description" class="pr-editor">${esc(e?.description||'')}</textarea></label>`;}
 else if(k==='event'){main=`<div class="pr-form-grid">${input('startAt','Empieza',localInput(e?.startAt),'datetime-local')}${input('endAt','Termina',localInput(e?.endAt),'datetime-local')}</div>${input('location','Ubicación',e?.location||'')}${select('status','Estado',{scheduled:'Programado',done:'Completado',cancelled:'Cancelado'},e?.status||'scheduled')}${input('description','Descripción',e?.description||'')}`;}
 else if(k==='reminder'){main=`${input('dueAt','Fecha y hora',localInput(e?.dueAt),'datetime-local')}${select('status','Estado',{pending:'Pendiente',done:'Completado',cancelled:'Cancelado'},e?.status||'pending')}<label class="pr-full"><span><input type="checkbox" name="notify" ${e?.notify!==false?'checked':''}> Enviar notificación Bookshell</span></label><small class="pr-muted pr-full">Recordatorio de una sola vez. Se registra si el servidor acepta el aviso.</small>${input('description','Descripción',e?.description||'')}${select('taskId','Vincular a tarea (opcional)',{'':'Independiente',...Object.fromEntries(tasks.map(t=>[t.id,t.title]))},e?.taskId||'')}`;}
 else if(k==='purchase'){main=`<div class="pr-form-grid">${input('quantity','Cantidad',e?.quantity??1,'number')}${input('unitCost','Coste unitario',e?.unitCost??0,'number')}${select('currency','Moneda',{EUR:'EUR',CHF:'CHF',USD:'USD'},e?.currency||'EUR')}${select('status','Estado',{planned:'Prevista',ordered:'Pedida',received:'Recibida'},e?.status||'planned')}${input('supplier','Proveedor',e?.supplier||'')}${input('dueAt','Entrega estimada',localInput(e?.dueAt),'datetime-local')}</div>${input('description','Descripción',e?.description||'')}`;}
 else if(k==='inventory'){main=`<div class="pr-form-grid">${input('quantity','Existencias',e?.quantity??0,'number')}${input('minimum','Mínimo',e?.minimum??0,'number')}${input('unit','Unidad',e?.unit||'uds')}${input('location','Ubicación',e?.location||'')}</div>${input('description','Descripción',e?.description||'')}`;}
 const d=dialog((e?'Editar ':'Nueva ')+labels[k],`<form class="pr-entry-form"><div class="pr-entry-main">${input('title','Título',e?.title||'')}${select('projectId','Proyecto',options,projectId)}${main}${k==='task'?reminderEditor(e):''}<p class="pr-notice pr-full">${rich?'Texto y enlaces en Markdown':'Fechas en '+esc(timeZone)}</p>${advanced}</div><footer class="pr-form-actions">${e?button('Eliminar','delete-entry','','danger'):''}${button('Cancelar','close')}<button class="pr-button primary" type="submit">Guardar</button></footer></form>`);
 d.querySelector('form').dataset.kind=k;d.querySelector('[data-action=close]').onclick=()=>d.close();const projectSelect=d.querySelector('[name=projectId]');if(e)projectSelect.disabled=true;projectSelect.onchange=ev=>{const next=S.projects.find(p=>p.id===ev.target.value);for(const row of d.querySelectorAll('.pr-dependency-list label'))row.remove();const list=d.querySelector('.pr-dependency-list');if(list)list.innerHTML=next.entries.filter(t=>t.kind==='task').map(t=>`<label><input type="checkbox" name="dependsOn" value="${t.id}"><span>${esc(t.title)}</span></label>`).join('');const parent=d.querySelector('[name=parentId]');if(parent)parent.innerHTML='<option value="">Sin tarea principal</option>'+next.entries.filter(t=>t.kind==='task').map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('');const linked=d.querySelector('[name=taskId]');if(linked)linked.innerHTML='<option value="">Independiente</option>'+next.entries.filter(t=>t.kind==='task').map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('');projectId=ev.target.value;};
 d.querySelector('[data-action=add-task-alert]')?.addEventListener('click',()=>{d.querySelector('.pr-custom-alerts').insertAdjacentHTML('beforeend',customAlertRow());});d.querySelector('[data-action=clear-task-alerts]')?.addEventListener('click',()=>{for(const c of d.querySelectorAll('[name=alertOffset]'))c.checked=false;d.querySelector('.pr-custom-alerts').innerHTML='';});d.querySelector('.pr-custom-alerts')?.addEventListener('click',ev=>{if(ev.target.closest('[data-action=remove-task-alert]'))ev.target.closest('.pr-custom-alert').remove();});
 d.querySelector('.pr-dependency-search')?.addEventListener('input',ev=>{const q=ev.target.value.toLowerCase();for(const row of d.querySelectorAll('.pr-dependency-list label'))row.hidden=!row.textContent.toLowerCase().includes(q);});
 if(k==='task'&&e){const shift=document.createElement('button');shift.type='button';shift.className='pr-button';shift.textContent='Reprogramar tareas dependientes';d.querySelector('.pr-advanced')?.append(shift);const removeButton=d.querySelector('[data-action=delete-entry]');if(removeButton)d.querySelector('.pr-advanced')?.append(removeButton);shift.onclick=async()=>{const answer=prompt('Días que se desplazarán esta tarea y sus dependientes pendientes:','1');if(answer===null)return;const days=Number(answer);if(!Number.isInteger(days)||Math.abs(days)>3650){formError(new Error('Introduce un número entero entre -3650 y 3650'));return;}try{await api('/projects/'+projectId+'/reschedule','POST',{taskId:e.id,days});d.close();await refresh();}catch(err){formError(err);}finally{d.querySelector('[type=submit]')?.removeAttribute('disabled');}};}
 d.querySelector('[data-action=delete-entry]')?.addEventListener('click',async()=>{if(!confirm('¿Eliminar este registro? El historial conservará una copia.'))return;try{await api('/projects/'+projectId+'/entries/'+e.id,'DELETE',{kind:k,version:e.version,confirmed:true});d.close();await refresh();}catch(err){formError(err);}});
 d.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget;const b=Object.fromEntries(new FormData(f));try{f.querySelector('[type=submit]')?.setAttribute('disabled','');document.querySelector(`[form="${f.id}"][type=submit]`)?.setAttribute('disabled','');const data={title:b.title,description:b.description||''};for(const key of ['status','priority','assignee','category','location','supplier','currency','unit','scheduleType'])if(b[key]!==undefined)data[key]=b[key];for(const key of ['startAt','dueAt','endAt'])if(b[key]!==undefined)data[key]=b[key]?instantFromInput(b[key],e?.[key]):null;for(const key of ['quantity','unitCost','minimum','estimatedMinutes'])if(b[key]!==undefined)data[key]=b[key]===''?null:Number(b[key]);if(k==='task'){data.archived=f.elements.archived.checked;data.reminders=[...Array.from(f.querySelectorAll('[name=alertOffset]:checked')).map(c=>{const offset=Number(c.value),old=e?.reminders?.find(r=>r.offsetMinutes===offset);return {...(old?{id:old.id}:{}),offsetMinutes:offset,enabled:true};}),...Array.from(f.querySelectorAll('[data-task-alert-at]')).map(c=>{const old=e?.reminders?.find(r=>r.id===c.dataset.alertId);return {...(old?{id:old.id}:{}),at:instantFromInput(c.value,old?.at),enabled:true};})];data.parentId=b.parentId||null;data.dependsOn=Array.from(f.querySelectorAll('[name=dependsOn]:checked')).map(x=>x.value);data.milestone=f.elements.milestone.checked;data.attachments=(b.attachmentsText||'').split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const i=line.indexOf('|');return {title:(i<0?'Adjunto':line.slice(0,i).trim())||'Adjunto',url:i<0?line.trim():line.slice(i+1).trim()};});}if(k==='reminder'){data.notify=f.elements.notify.checked;data.taskId=b.taskId||null;data.offsetMinutes=e?.taskId===data.taskId&&b.dueAt===localInput(e?.dueAt)?e?.offsetMinutes??null:null;}await api('/projects/'+(b.projectId||projectId)+'/entries'+(e?'/'+e.id:''),e?'PATCH':'POST',{kind:k,data,version:e?.version});d.close();await refresh();}catch(err){formError(err);}finally{d.querySelector('[type=submit]')?.removeAttribute('disabled');}};
}
async function richRender(el,markdown){el.innerHTML=DOMPurify.sanitize(marked.parse(markdown||''),{FORBID_TAGS:['style','form','input','button'],FORBID_ATTR:['style'],ALLOW_DATA_ATTR:false});for(const a of el.querySelectorAll('a')){a.target='_blank';a.rel='noopener noreferrer';}for(const img of el.querySelectorAll('img'))img.referrerPolicy='no-referrer';const codes=el.querySelectorAll('code.language-mermaid');if(codes.length){try{if(!window.mermaid){await new Promise((resolve,reject)=>{let s=document.createElement('script');s.src='./assets/vendors/projects/mermaid.js';s.onload=resolve;s.onerror=reject;document.head.append(s);});}window.mermaid.initialize({startOnLoad:false,securityLevel:'strict',theme:'dark'});for(const code of codes){const target=document.createElement('div');target.className='mermaid';target.textContent=code.textContent;code.parentElement.replaceWith(target);await window.mermaid.run({nodes:[target],suppressErrors:true});}}catch{const msg=document.createElement('p');msg.textContent='El diagrama no se pudo mostrar; revisa el código Mermaid.';el.append(msg);}}}
async function readEntry(e,pid){const d=dialog(e.title,`<p class="pr-muted">${esc(e.category)} · ${date(e.updatedAt)}</p><div class="pr-rich" id="projects-read"></div><footer>${button('Editar','edit')}</footer>`);await richRender(d.querySelector('#projects-read'),e.description);d.querySelector('[data-action=edit]').onclick=()=>entryForm(e.kind,e,pid);}
async function loadHistory(){try{const ps=projects();const data=await Promise.all(ps.map(async p=>({p,history:(await api('/projects/'+p.id+'/activity')).activity,deliveries:(await api('/projects/'+p.id+'/deliveries')).deliveries})));const el=document.getElementById('projects-history');if(!el)return;el.innerHTML=`<h2 class="pr-section-title">Historial de cambios</h2>${data.flatMap(({p,history})=>history.map(h=>({...h,projectTitle:p.title}))).sort((a,b)=>Number(b.seq)-Number(a.seq)).slice(0,100).map(h=>`<div class="pr-task"><div class="pr-task-content"><span class="pr-link">${esc(h.after_data?.title||h.before_data?.title||h.action)}</span><small>${esc(h.projectTitle)} · ${esc(h.action)} · ${new Date(h.created_at).toLocaleString('es-ES')}</small></div></div>`).join('')||empty('Sin actividad')}<h2 class="pr-section-title" style="margin-top:22px">Seguimiento de notificaciones</h2>${data.flatMap(d=>d.deliveries).map(d=>`<p class="pr-muted">${esc(d.status)} · ${date(d.updated_at)} · Intentos: ${d.attempts} ${esc(d.error||'')}</p>`).join('')||empty('Todavía no hay notificaciones programadas que hayan vencido')}`;}catch(e){notice(e.message);}}
async function access(){try{const {tokens}=await api('/projects/access');const d=dialog('Conexión con ChatGPT',`<div class="pr-access"><p>Proyectos se abre directamente desde Bookshell en este navegador, en el móvil y en la aplicación instalada. No hay inicio de sesión ni enlace de activación.</p><p>Conexión MCP: <a href="https://mcp-bookshell.charlydob.com/mcp" target="_blank" rel="noopener">Bookshell Proyectos</a></p><p>Conexiones activas: ${new Set(tokens.map(t=>t.client_id)).size}</p><div class="pr-actions">${button('Generar código para ChatGPT','pair','','primary')}</div><div id="projects-pair-code"></div><p class="pr-muted">El código inicial se usa una vez. La conexión permanece activa hasta que se revoque.</p>${button('Revocar conexiones MCP','revoke','','danger')}</div>`);d.querySelector('[data-action=pair]').onclick=async()=>{try{const r=await api('/projects/access-code','POST',{});const box=d.querySelector('#projects-pair-code');box.innerHTML=`<label>Código de conexión<input readonly value="${esc(r.ticket)}" aria-label="Código de conexión"></label><p class="pr-notice">Cópialo en la pantalla de conexión de ChatGPT. Caduca en diez minutos y se usa una vez.</p>`;box.querySelector('input').select();}catch(e){formError(e);}};d.querySelector('[data-action=revoke]').onclick=async()=>{if(!confirm('¿Revocar todas las conexiones MCP?'))return;try{await api('/projects/access','DELETE',{confirmed:true});d.close();}catch(e){formError(e);}};}catch(e){notice(e.message);}}
function library(){const ps=S.projects.filter(p=>p.template||p.status==='archived');const d=dialog('Plantillas y archivo',ps.map(p=>`<div class="pr-card"><span class="pr-pill">${p.template?'Plantilla':'Archivado'}</span><h3>${esc(p.title)}</h3>${button('Abrir','open',`data-id="${p.id}"`)}</div>`).join('')||empty('Los proyectos archivados y las plantillas aparecerán aquí.'));for(const b of d.querySelectorAll('[data-action=open]'))b.onclick=()=>{S.selected=b.dataset.id;d.close();render();};}
async function setTask(t,pid,status){
 if(S.pendingTasks.has(t.id))return;const before=structuredClone(S.projects),p=S.projects.find(x=>x.id===pid),local=p.entries.find(x=>x.id===t.id),version=t.version;
 S.pendingTasks.add(t.id);local.status=status;
 for(const r of p.entries.filter(e=>e.kind==='reminder'&&e.taskId===t.id))if(status==='done'&&r.status==='pending'){r.status='cancelled';r.suspensionReason='task_done';}
 for(const r of local.reminders||[])if(status==='done'&&r.status==='pending')r.status='cancelled';
 const tasks=p.entries.filter(e=>e.kind==='task'&&!e.archived);p.stats.done=tasks.filter(t=>t.status==='done').length;p.stats.taskProgress=tasks.length?Math.round(p.stats.done/tasks.length*100):0;render();
 let error;try{await api(`/projects/${pid}/entries/${t.id}`,'PATCH',{kind:'task',version,data:{status}});}catch(e){error=e;S.projects=before;}finally{S.pendingTasks.delete(t.id);if(!S.pendingTasks.size)await refresh();else render();if(error)notice(error.message);}
}
async function loadOverviewActivity(){try{const ps=projects();const histories=await Promise.all(ps.map(async p=>(await api('/projects/'+p.id+'/activity')).activity.map(h=>({...h,projectTitle:p.title}))));const el=document.getElementById('projects-overview-activity');if(el)el.innerHTML=histories.flat().sort((a,b)=>Number(b.seq)-Number(a.seq)).slice(0,4).map(h=>`<div class="pr-activity-item"><strong>${esc(h.after_data?.title||h.before_data?.title||h.action)}</strong><small>${esc(h.projectTitle)} · ${new Date(h.created_at).toLocaleString('es-ES',{timeZone})}</small></div>`).join('')||empty('Sin actividad reciente');}catch{const el=document.getElementById('projects-overview-activity');if(el)el.textContent='No se pudo cargar la actividad';}}
function bind(){const root=document.getElementById('projects-app');root.onclick=ev=>{const day=ev.target.closest('[data-day]');if(day){dayAgenda(day.dataset.day);return;}const open=ev.target.closest('[data-open]');if(open){S.selected=open.dataset.open;render();return;}const edit=ev.target.closest('[data-edit]');if(edit){const e=findEntry(edit.dataset.edit,edit.dataset.project);entryForm(e.kind,e,edit.dataset.project);return;}const read=ev.target.closest('[data-read]');if(read){void readEntry(findEntry(read.dataset.read,read.dataset.project),read.dataset.project);return;}const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='global'){S.selected=null;S.tab='overview';render();return;}if(a==='more'){moreMenu();return;}if(a==='focus'){S.focus=b.dataset.focus;render();return;}if(a==='tab'){S.tab=b.dataset.tab;S.search='';S.filter='all';render();if(S.tab==='today')void refresh();}if(a==='new-project')projectForm();if(a==='edit-project')projectForm(current());if(a==='new-entry')entryForm(b.dataset.kind);if(a==='edit-entry'){const e=findEntry(b.dataset.id,b.dataset.project);entryForm(e.kind,e,b.dataset.project);}if(a==='refresh')void refresh();if(a==='access')void access();if(a==='library')library();if(a==='today'){S.month=new Date();render();dayAgenda(dayKey(new Date()));}if(a==='month'){S.month=new Date(S.month.getFullYear(),S.month.getMonth()+Number(b.dataset.delta),1);render();}};
root.querySelector('#projects-select').onchange=e=>{S.selected=e.target.value||null;render();};root.querySelector('#projects-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;S.search=e.target.value;render();const input=root.querySelector('#projects-search');input.focus();input.setSelectionRange(pos,pos);});root.querySelector('#projects-filter')?.addEventListener('change',e=>{S.filter=e.target.value;render();});for(const c of root.querySelectorAll('[data-toggle]'))c.onchange=()=>void setTask(findEntry(c.dataset.toggle,c.dataset.project),c.dataset.project,c.checked?'done':'todo');for(const card of root.querySelectorAll('[data-open]'))card.onkeydown=e=>{if(e.key==='Enter'){S.selected=card.dataset.open;render();}};for(const card of root.querySelectorAll('[data-drag]'))card.ondragstart=e=>e.dataTransfer.setData('text/plain',JSON.stringify({id:card.dataset.drag,pid:card.dataset.project}));for(const col of root.querySelectorAll('[data-drop]')){col.ondragover=e=>e.preventDefault();col.ondrop=e=>{e.preventDefault();try{const b=JSON.parse(e.dataTransfer.getData('text/plain'));const t=findEntry(b.id,b.pid);if(t)void setTask(t,b.pid,col.dataset.drop);}catch{}};}}
export async function init(){/* Rendering is owned by onShow to avoid duplicate requests. */}
export async function onShow(){if(new URL(location.href).searchParams.get('agenda')==='today'){S.selected=null;S.tab='today';S.focus='0';}await refresh();clearInterval(S.timer);S.timer=setInterval(()=>{if(!document.hidden&&!document.getElementById('projects-dialog')?.open&&S.ready)void refresh();},20000);}
export function onHide(){clearInterval(S.timer);document.getElementById('projects-dialog')?.close();}
export function destroy(){onHide();}
